#[repr(u32)]
#[derive(Copy, Clone, PartialEq, Eq, Hash, PartialOrd, Ord, Debug, Default)]
pub enum TerminatorKind {
    #[default] Jump = 0, Branch = 1, Switch = 2, SwitchString = 3, Return = 4, ReturnCall = 5, Throw = 6, Rethrow = 7, Unreachable = 8
}
impl TerminatorKind {
    pub const COUNT: usize = 9;
    pub const ALL: [TerminatorKind; 9] = [
        TerminatorKind::Jump, TerminatorKind::Branch, TerminatorKind::Switch, TerminatorKind::SwitchString, TerminatorKind::Return,
        TerminatorKind::ReturnCall, TerminatorKind::Throw, TerminatorKind::Rethrow, TerminatorKind::Unreachable
    ];
    pub const NAMES: [&'static str; 9] = ["Jump", "Branch", "Switch", "SwitchString", "Return", "ReturnCall", "Throw", "Rethrow", "Unreachable"];
    pub const fn name(self) -> &'static str { Self::NAMES[self as usize] }
    pub fn from_name(name: &str) -> Option<TerminatorKind> { Self::ALL.into_iter().find(|member| member.name() == name) }
    pub const fn to_wire(self) -> u32 { self as u32 }
    pub const fn from_wire(word: u32) -> Option<TerminatorKind> { if (word as usize) < Self::COUNT { Some(Self::ALL[word as usize]) } else { None } }
}

impl TerminatorKind {
    pub fn target_name(self, index: usize, target_count: usize) -> Option<&'static str> {
        match self {
            TerminatorKind::Jump => ["next"].get(index).copied(),
            TerminatorKind::Branch => ["taken", "notTaken"].get(index).copied(),
            TerminatorKind::Switch if index + 1 < target_count => Some("case"),
            TerminatorKind::Switch if index + 1 == target_count => Some("otherwise"),
            TerminatorKind::Switch => None,
            TerminatorKind::SwitchString if index + 1 < target_count => Some("case"),
            TerminatorKind::SwitchString if index + 1 == target_count => Some("otherwise"),
            TerminatorKind::SwitchString => None,
            TerminatorKind::Return => None,
            TerminatorKind::ReturnCall => None,
            TerminatorKind::Throw => None,
            TerminatorKind::Rethrow => None,
            TerminatorKind::Unreachable => None,
        }
    }
}

